# Global rights per group (node=None applies everywhere). Superusers bypass all checks anyway.
GROUPS = {
    "Admin": dict(can_read=True, can_write=True, can_publish=True, can_manage=True),
    "IT-Team": dict(can_read=True, can_write=True, can_publish=True, can_manage=False),
    "Leser": dict(can_read=True, can_write=False, can_publish=False, can_manage=False),
}
FAQ = "FAQ für Anwender"
WELCOME = ("<p>Hier stehen Anleitungen und Antworten für alle Anwender. Diese Seiten sind ohne Anmeldung lesbar.</p>"
           "<p>Neue Seiten erscheinen hier erst, wenn sie veröffentlicht sind.</p>")


def setup(apps, schema_editor):
    Group = apps.get_model("auth", "Group")
