    NodePermission = apps.get_model("core", "NodePermission")
    Node = apps.get_model("core", "Node")
    PageRevision = apps.get_model("core", "PageRevision")
    for name, flags in GROUPS.items():
        group, _ = Group.objects.get_or_create(name=name)
        NodePermission.objects.update_or_create(node=None, group=group, defaults=flags)
    # Until now every logged-in user could do everything: existing accounts keep that as IT-Team (admin stays superuser).
    it_team, admins = Group.objects.get(name="IT-Team"), Group.objects.get(name="Admin")
    for user in User.objects.all():
        user.groups.add(admins if user.is_superuser else it_team)
    if Node.objects.filter(parent=None, kind="area", title=FAQ, deleted_at=None).exists():
        return
    last = Node.objects.filter(parent=None, space="wiki").order_by("-position").first()
    area = Node.objects.create(kind="area", space="wiki", title=FAQ, is_public=True, status="published",
                               position=(last.position + 1) if last else 0,
                               description="Öffentlich: ohne Anmeldung lesbar, nur veröffentlichte Seiten.")
    page = Node.objects.create(parent=area, kind="page", space="wiki", title="Willkommen", status="published",
                               version=2, search_text="Hier stehen Anleitungen und Antworten für alle Anwender.")
    PageRevision.objects.create(node=page, content={}, content_html=WELCOME, comment="Angelegt bei der Einrichtung")


